            </DialogContent>
            <DialogActions>
              <Button
                appearance="primary"
                onClick={handleDelete}
                disabled={isMutating}
              >
                Confirm
              </Button>
              <Button appearance="subtle" onClick={() => setConfirmDelete(false)}>
                Cancel
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>
    )
  }

  return (
    <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
      <DialogSurface>
        <DialogBody>
